import vtkImageMapper from '@kitware/vtk.js/Rendering/Core/ImageMapper.js';
import vtkImageSlice from '@kitware/vtk.js/Rendering/Core/ImageSlice.js';
import CanvasActor from '../../CanvasActor/index.js';
import { ActorRenderMode } from '../../../types/index.js';
import uuidv4 from '../../../utilities/uuidv4.js';
import { createVTKImageDataFromImage } from '../../helpers/planarImageRendering.js';
export function createPlanarImageOverlayActorEntry(image, stackInput) {
    const mapper = vtkImageMapper.newInstance();
    const actor = vtkImageSlice.newInstance();
    const imageData = createVTKImageDataFromImage(image);
    mapper.setInputData(imageData);
    actor.setMapper(mapper);
    if (typeof stackInput.visibility === 'boolean') {
        actor.setVisibility(stackInput.visibility);
    }
    return {
        uid: uuidv4(),
        actor,
        actorMapper: {
            actor,
            mapper,
            renderMode: ActorRenderMode.VTK_IMAGE,
        },
        referencedId: image.imageId,
        ...stackInput,
    };
}
export function createPlanarCpuImageOverlayActorEntry(viewport, image, stackInput) {
    const actor = new CanvasActor(viewport, image);
    actor.setVisibility(typeof stackInput.visibility === 'boolean' ? stackInput.visibility : true);
    return {
        uid: uuidv4(),
        actor,
        actorMapper: {
            actor,
            mapper: actor.getMapper(),
            renderMode: ActorRenderMode.CPU_IMAGE,
        },
        referencedId: image.imageId,
        ...stackInput,
    };
}
